// موازنة أطوال الخيارات: حتى لا يكون الجواب الصحيح هو الأطول دائمًا.
// bal(المعرّف, الصحيح, خطأ, خطأ, خطأ) — المعرّف «الجزء:رقم السؤال» كما في ملف المراجعة.
// يُحمَّل بعد ملفات الأسئلة وملف التوثيق، ويستبدل خيارات السؤال المعني فقط.
const BALANCE = {};
function bal(id, ...o) { BALANCE[id] = o; }

