bal("27:15", "أن الإنسان يُجزى بعمله", "أن الرزق يُنال بالسعي وحده", "أن الدعاء لا ينفع أحدًا", "منع الصدقة عن الأموات");
bal("27:16", "الإيمان بالقدر", "أن الأشياء خُلقت صدفة بلا تقدير", "أن القدر يختص بالشر دون الخير", "أن الإنسان مجبور لا عمل له");
bal("27:17", "سهّلنا لفظه ومعناه", "جعلناه قصيرًا قليل الآيات", "جعلناه خاليًا من الأحكام", "يسّرنا كتابته على الصحابة فقط");
bal("27:19", "لذكر إنزال الحديد فيها", "لشدة أحكامها وقوة وعيدها", "لذكر سدّ ذي القرنين من الحديد", "لأنها نزلت في أثناء غزوة");
bal("27:24", "أصناف الناس الثلاثة في أولها وآخرها", "لا مناسبة بين أول السورة وآخرها", "افتُتحت بالأحكام وخُتمت بالقصص", "أولها وآخرها في وصف الجنة فقط");
bal("27:25", "تجادلونه / تجحدونه", "لا فرق بين القراءتين في المعنى", "كلتاهما بمعنى: تصدّقونه وتتبعونه", "كلتاهما بمعنى: تسألونه وتستفهمونه");
bal("27:26", "لا بشيء من نعمك ربنا نكذّب، فلك الحمد", "سمعنا وأطعنا غفرانك ربنا وإليك المصير", "آمنا بالله وحده وكفرنا بما كنا به نشرك", "سبحان ربنا إن كان وعد ربنا لمفعولًا");
bal("27:27", "اشتراط الطهارة لمسّ المصحف", "تحريم قراءة القرآن على المحدث", "تحريم كتابة المصحف بغير العربية", "وجوب الغسل قبل كل قراءة");
bal("27:28", "مرتبة الكتابة", "مرتبة الاختيار الإنساني", "نفي القدر السابق", "مرتبة الأسباب الظاهرة فقط");
bal("27:29", "من أقوى صيغ العموم", "تدل على بعض الأفراد فقط", "تدل على الخصوص لا العموم", "لا دلالة لها عند الأصوليين");
bal("27:30", "طمأنينة القلب", "ترك العمل والاكتفاء بالتوكل", "الحزن الدائم على ما فات", "التفاخر بما أُوتي الإنسان");
bal("27:31", "مبتدأ، والجملة بعده خبره", "فاعل لفعل محذوف تقديره: علّم", "مفعول به مقدّم للفعل «علّم»", "منادى حُذفت منه أداة النداء");

// ======================= الجزء 26 =======================
bal("26:0", "طويلات مرتفعات", "مثمرات كثيرة الحمل", "قصيرات متقاربات", "يابسات لا ثمر لها");
bal("26:2", "اختلاف أبي بكر وعمر حتى ارتفعت أصواتهما", "صياح الأعراب عند حجرات النبي ﷺ", "جدال اليهود في المسجد النبوي", "رفع الأذان بصوت عالٍ قرب بيوت النبي ﷺ");
bal("26:3", "عند الانصراف من الحديبية", "يوم فتح مكة", "بعد غزوة خيبر مباشرة", "يوم غزوة بدر");
bal("26:4", "تمثيل تنفيري", "طباق إيجاب بين الحياة والموت", "جناس ناقص بين «أخيه» و«ميتًا»", "مدح بما يشبه الذم");
bal("26:6", "الأدب مع الله ورسوله، وأخلاق المجتمع", "قصص الأنبياء السابقين مع أقوامهم", "أحكام المواريث وتقسيم التركات", "أهوال يوم القيامة وأحوال الآخرة");
bal("26:10", "وفد بني تميم", "جماعة من الأنصار", "وفد نصارى نجران", "يهود بني قينقاع");
bal("26:11", "الوليد بن عقبة وصدقات بني المصطلق", "حادثة الإفك وما أشاعه المنافقون", "خبر استشهاد القادة في غزوة مؤتة", "رسالة حاطب بن أبي بلتعة إلى قريش");
bal("26:12", "نموّ الصحابة من قلة إلى قوة", "وصف الزراعة في نخيل المدينة", "حال المنافقين وتقلّبهم", "قصة أصحاب الجنة في سورة القلم");
bal("26:13", "استعارة", "تشبيه بليغ", "كناية عن النوم", "مجاز عقلي");
bal("26:14", "المبالغة في القرب والعلم", "وصف عِرق في اليد قريب من القلب", "التهديد بالقتل وقطع الوريد", "بيان مكان القلب في الصدر");
bal("26:16", "وجوب تدبّر القرآن", "تحريم قراءة القرآن دون الرجوع إلى تفسير", "أن معاني القرآن لا يمكن فهمها", "الأمر بإغلاق الأبواب عند التلاوة");
bal("26:17", "أن الاقتتال لا يُخرج من الإيمان", "أن القتال بين المؤمنين جائز مطلقًا", "أنهم خرجوا من الإسلام بالقتال", "أن الصلح بينهم ليس واجبًا");
bal("26:18", "مساكن قوم عاد", "جبال مكة المحيطة بها", "وادي النمل في الشام", "أرض مملكة سبأ في اليمن");
bal("26:19", "يخطب بها على المنبر يوم الجمعة", "يقرؤها على المريض للرقية", "يقرؤها عند النوم كل ليلة", "يقرؤها في صلاة الجنازة");
bal("26:20", "أحبّ إليّ مما طلعت عليه الشمس", "هي تعدل ثلث القرآن الكريم", "هي قلب القرآن ولبّه", "هي أعظم سورة في القرآن");
bal("26:23", "مدنية؛ لنزولها بعد الهجرة", "مكية؛ لنزولها قريبًا من مكة", "لا توصف بمكية ولا بمدنية", "مكية ومدنية معًا لأنها في الطريق");
bal("26:24", "من الأدب مع الله ورسوله إلى الناس جميعًا", "من الأحكام الفقهية إلى القصص والأخبار", "من وصف الجنة إلى وصف النار", "بلا ترتيب معيّن بين موضوعاتها");
bal("26:25", "معنيان متكاملان", "لا فرق بين القراءتين أصلًا", "«حسنًا» تعني الجمال الظاهر", "إحداهما للأم والأخرى للأب");
bal("26:26", "جلس في بيته يبكي فبشّره ﷺ بالجنة", "خرج للجهاد في أول سرية بعدها", "هاجر إلى الحبشة فرارًا بدينه", "اعتزل الناس وترك الكلام مدة");
bal("26:27", "محرّمان", "مكروهان كراهة تنزيه", "مباحان عند الحاجة دائمًا", "مستحبان لإصلاح الناس");
bal("26:29", "قبول خبر العدل الواحد", "ردّ أخبار الآحاد كلها", "قبول خبر الفاسق دون تثبّت", "تحريم نقل الأخبار مطلقًا");
bal("26:30", "قلب حيّ وسمع مصغٍ وحضور ذهن", "كثرة المال والفراغ من الشواغل", "الذكاء والفطنة وحدهما", "السفر والاعتبار بآثار الأمم");

// ======================= الجزء 25 =======================
bal("25:0", "ساكنًا منفرجًا", "هائجًا شديد الموج", "مُظلمًا لا يُرى قاعه", "متجمّدًا كالحجر");
bal("25:2", "ما أصاب قريشًا من القحط والجوع", "دخان حرائق الحروب بين القبائل", "دخان بركان ظهر في جزيرة العرب", "دخان قرابين المشركين حول الأصنام");
bal("25:3", "كناية عن هوانهم", "وصف لصفاء الجو يوم غرقهم", "حقيقة لغوية لا مجاز فيها", "مدح لصبرهم على العذاب");
bal("25:4", "نفي المماثلة مع إثبات الصفات", "نفي الصفات كلها عن الله", "أن صفات الله كصفات المخلوقين", "أن الله لا يسمع إلا القرآن");
bal("25:8", "ذريّته ونسله", "قدمه وأثر مشيه", "آخر عمره وخاتمته", "بيته وأهل داره");
bal("25:10", "جدالهم بعيسى عليه السلام", "قدوم وفد نصارى نجران إلى المدينة", "سؤال اليهود عن مريم وولادتها", "هجرة المسلمين الأولى إلى الحبشة");
bal("25:12", "أبو جهل", "أبو لهب", "فرعون", "قارون");
bal("25:13", "تشبيهان متتابعان", "طباق بين الحار والبارد", "استفهام إنكاري توبيخي", "كناية عن الكرم والضيافة");
bal("25:15", "بالجبال", "بالطيور في سرعتها", "بالنجوم في هدايتها", "بالبيوت في سكنها");
bal("25:16", "صداقة المتقين", "صداقة القرابة والنسب", "صداقة المصالح والتجارة", "كل الصداقات بلا استثناء");
bal("25:17", "أن المصائب بسبب الذنوب، والله يعفو", "أن المصائب لا سبب لها ولا حكمة", "أن الله يؤاخذ بكل ذنب ولا يعفو", "أن المصائب تصيب الكفار وحدهم");
bal("25:18", "من وصف المؤمنين بالتشاور", "من مجلس شورى قريش في دار الندوة", "من مشاورة موسى لأخيه هارون", "من قصة ملكة سبأ ومشاورتها قومها");
bal("25:20", "جثوّ الأمم على الركب", "سجود السحرة لربّ موسى", "نزول الملائكة يوم القيامة", "خروج يأجوج ومأجوج");
bal("25:24", "افتُتحت بالوحي وخُتمت به", "لا مناسبة بين أولها وآخرها", "افتُتحت بالقصص وخُتمت بالأحكام", "خُتمت بأحكام الشورى والزكاة");
bal("25:25", "إثبات عبوديتهم وقربهم", "لا فائدة في اختلاف القراءتين", "«عند» تعني المكان الحسي فقط", "«عباد» تعني الخدم من البشر");
bal("25:26", "الدخان والقمر والروم والبطشة واللزام", "الصلوات الخمس المفروضة على الأمة", "أركان الإسلام الخمسة كما في الحديث", "الغزوات الخمس الكبرى في حياة النبي ﷺ");
bal("25:27", "جواز المعاقبة بالمثل مع ندب العفو", "وجوب الانتقام من كل معتدٍ", "تحريم القصاص في كل الأحوال", "جواز الزيادة على المثل في العقوبة");
bal("25:28", "وحيًا، أو من وراء حجاب، أو برسول", "طريق واحد هو الرؤيا الصادقة", "الأحلام والإلهام فقط", "الكتب المنزلة دون غيرها");
bal("25:29", "التقليد الأعمى", "طاعة الوالدين في المعروف", "طلب العلم من أهله", "الاقتداء بالأنبياء والصالحين");
bal("25:30", "خطر اتباع الهوى", "فضل اتباع الرغبات والميول", "مدح الحرية المطلقة في الاختيار", "الحث على العزلة عن الناس");

// ======================= الجزء 24 =======================
bal("24:0", "مفاتيح وخزائن", "قلائد وزينة", "أبواب مغلقة محكمة", "جبال راسية ثابتة");
bal("24:2", "مشركون أسرفوا ثم سألوا عن الكفارة", "توبة كعب بن مالك بعد تخلّفه عن تبوك", "إسلام وحشي قاتل حمزة بعد فتح مكة", "قصة أصحاب الأخدود وتعذيب المؤمنين");
bal("24:3", "أن أبواب الجنة مفتّحة قبل مجيئهم", "أن الواو زائدة لا معنى لها", "أن أبواب النار أكثر من أبواب الجنة", "أنها لتحسين الإيقاع والوزن فقط");
bal("24:5", "مقابلة الإساءة بالإحسان", "مقاطعة المسيء وهجره", "الانتقام منه بالمثل", "السكوت عنه دون إصلاح");
bal("24:8", "ارجعوا إليه بالتوبة", "اجتمعوا على كلمة واحدة", "انتظروا أمر الله", "اسألوا أهل الذكر");
bal("24:11", "ثلاثة تساءلوا: أيسمع الله ما نقول؟", "منافقون تآمروا في المدينة ليلًا", "أهل الكتاب الذين كتموا صفة النبي ﷺ", "أصحاب الفيل لما قصدوا هدم الكعبة");
bal("24:12", "المشرك الموزّع والموحّد الخالص", "حال العبيد والإماء في الجاهلية", "أحكام الشراكة في التجارة", "الخلاف بين الأخوين على الميراث");
bal("24:13", "استعارة", "تشبيه تمثيلي صريح الأداة", "كناية عن الخصب والنماء", "طباق بين الخشوع والاهتزاز");
bal("24:14", "النفي والإنكار", "طلب المعرفة والفهم", "التمني والترجّي", "الأمر والإلزام");
bal("24:15", "أن النوم وفاة صغرى", "أن النوم لا علاقة له بالروح", "أن النائم لا يُبعث يوم القيامة", "أن الأحلام كلها وحي صادق");
bal("24:16", "تتنزل عليهم الملائكة بالبشرى", "يُعطَون الملك والسلطان في الدنيا", "لا يُحاسبون يوم القيامة أبدًا", "يُرفعون إلى السماء وهم أحياء");
bal("24:17", "لسوق الناس إلى الجنة والنار جماعات", "لكثرة ذكر المزامير والمعازف فيها", "لاجتماع الأنبياء في آخرها", "لذكر الملائكة صفوفًا حول العرش");
bal("24:18", "حم السجدة", "المؤمن", "الطَّوْل", "المصابيح");
bal("24:19", "الجمع بين الترغيب والترهيب", "الترهيب وحده دون ترغيب", "وصف الجنة ونعيمها", "قصص الأنبياء مع أقوامهم");
bal("24:23", "لما جاءه حَبر يذكر عظمة الله", "يوم بدر وهو يدعو على المشركين", "عند نزول المطر بعد القحط", "في خطبة الوداع بعرفة");
bal("24:24", "بعد صلاح النفس ذكر إصلاح الغير", "لا مناسبة بين الآيتين", "الانتقال من الأحكام إلى القصص", "بيان أحكام الصلاة والأذان");
bal("24:25", "الإفراد للنبي ﷺ والجمع للمؤمنين", "لا فائدة في اختلاف القراءتين", "الجمع للملائكة المقربين فقط", "الإفراد لموسى عليه السلام");
bal("24:26", "«إنكم تخطئون… وأنا أغفر الذنوب جميعًا»", "«إنما الأعمال بالنيات وإنما لكل امرئ ما نوى»", "«الدين النصيحة لله ولكتابه ولرسوله»", "«من حسن إسلام المرء تركه ما لا يعنيه»");
bal("24:27", "تحريم السجود لغير الله", "جواز السجود للشمس تعظيمًا", "وجوب صلاة الكسوف فقط", "تحريم النظر إلى القمر");
bal("24:28", "تسبيح حملة العرش واستغفارهم للمؤمنين", "أن الملائكة لا عمل لها ولا وظيفة", "أن الملائكة تعبد البشر وتخدمهم", "أن الملائكة بنات الله كما زعموا");
bal("24:29", "اختلاف المحل: التائب ومن مات مشركًا", "تعارض بين الآيتين لا يمكن رفعه", "آية النساء منسوخة بآية الزمر", "آية الزمر منسوخة بآية النساء");
bal("24:30", "الجمع بين الخوف والرجاء", "الخوف وحده", "الرجاء وحده", "ترك الخوف والرجاء");

// ======================= الجزء 23 =======================
bal("23:0", "عِذق النخلة اليابس المنحني", "سيف قديم مقوّس النصل", "قوس مكسور لا يُرمى به", "غصن زيتون جافّ");
bal("23:2", "مشرك فتّ عظمًا باليًا منكرًا البعث", "سؤال اليهود عن الروح وحقيقتها", "طلب قريش نزول الملائكة عيانًا", "سؤال قريش عن أصحاب الكهف");
bal("23:3", "تشبيه بمتخيَّل قبيح للتنفير", "لأنها رُئيت فعلًا في المنام", "لأن الشياطين جميلة الصورة", "للمحافظة على السجع والفاصلة فقط");
bal("23:6", "توحيد الله", "تحريم الخمر والميسر", "فرض صيام رمضان", "تحويل القبلة إلى الكعبة");
bal("23:8", "ميّتون ساكنون", "نائمون نومًا عميقًا", "هاربون من العذاب", "صامتون من شدة الخوف");
bal("23:10", "شكوى قريش عند أبي طالب ودعوتهم إلى التوحيد", "جدال اليهود في المدينة حول نبوة عيسى", "قدوم أبرهة بالفيل لهدم الكعبة", "خروج النبي ﷺ إلى الطائف يدعو ثقيفًا");
bal("23:11", "رغبة بني سلمة في الانتقال قرب المسجد", "سؤال الصحابة عن كتابة الوحي", "كتابة صحيفة المقاطعة في الكعبة", "كتابة وثيقة صلح الحديبية");
bal("23:12", "استعارة", "تشبيه بليغ", "كناية عن الصباح", "مجاز مرسل");
bal("23:13", "الصفاء والصيانة", "الصلابة وشدة التماسك", "الصغر ودقة الحجم", "البياض الشديد وحده دون غيره");
bal("23:14", "التهكم", "المدح والإكرام", "التشبيه التمثيلي", "الطباق بين الخير والشر");
bal("23:15", "أن يكون القرآن شعرًا", "أن يكون للنبي ﷺ علم بالكتابة", "تحريم الشعر في كل أحواله", "أن يحفظ النبي ﷺ القرآن");
bal("23:17", "أصحاب القرية والرجل الساعي", "أصحاب الكهف والرقيم", "قوم لوط والملائكة", "صاحب الجنتين وصاحبه");
bal("23:18", "الملائكة", "الطيور الصافّات في الجو", "الخيل الصافنات", "صفوف المصلين في المسجد");
bal("23:23", "زعم النسب بين الله والملائكة والجن", "قول اليهود: عزير ابن الله", "إنكار المشركين للبعث والحساب", "عبادة الشمس والقمر من دون الله");
bal("23:24", "تتويج أدلة البعث بتنزيه القادر", "خُتمت السورة بقصة جديدة لا صلة لها", "لا مناسبة بين خاتمتها وموضوعها", "خُتمت بأحكام فقهية مفصلة");
bal("23:25", "لئلا يُظن «هذا» صفةً لـ«مرقدنا»", "للتنفس وأخذ النفس فقط", "لأن «مرقدنا» نهاية آية", "ليس في الموضع سكت عند حفص");
bal("23:26", "«لا تزول قدما عبد…»", "«بُني الإسلام على خمس…»", "«المسلم من سلم المسلمون من لسانه ويده»", "«الحياء شعبة من الإيمان»");
bal("23:27", "ليست من العزائم، والنبي ﷺ سجد فيها", "لا يُسجد فيها أبدًا لأنها توبة نبي", "هي سجدة واجبة كسائر سجدات القرآن", "هي سجدة شكر خاصة بالمرأة");
bal("23:28", "أن الله خالق العباد وأفعالهم", "أن العبد يخلق أفعاله بنفسه", "نفي القدر السابق", "أن الأصنام تخلق شيئًا");
bal("23:29", "جواز النسخ قبل التمكن من الفعل", "تخصيص العام بالخاص", "حجية القياس", "مفهوم المخالفة");
bal("23:30", "محاورة الابن ليستسلم عن قناعة", "القسوة على الأبناء في التربية", "ترك الأمر الإلهي إذا كرهه الابن", "الاستبداد بالرأي دون مشاورة");

// ======================= الجزء 22 =======================
bal("22:0", "القشرة الرقيقة على النواة", "حبة القمح الصغيرة", "ورق الشجر اليابس", "قطرة الماء");
bal("22:2", "إبطال التبنّي", "غزوة الخندق وحصار المدينة", "حادثة الإفك وبراءة عائشة", "تحويل القبلة إلى الكعبة");
bal("22:3", "قصر بتقديم المفعول", "استفهام إنكاري توبيخي", "أمر يفيد الإباحة", "تشبيه تمثيلي");
bal("22:4", "التكاليف الشرعية", "الودائع المالية فقط", "أسرار الناس وعوراتهم", "الأرض الزراعية والعقار");
bal("22:5", "من أدّى الواجبات وزاد بالمستحبات", "من ترك بعض الواجبات وفعل الطاعات", "من اقتصر على الواجبات وحدها", "من سبق الناس إلى الدنيا ومكاسبها");
bal("22:6", "عاقبة كفران النعمة", "فضل التجارة بين البلدان", "أهمية بناء السدود وحفظ المياه", "قوة الملوك وسعة ممالكهم");
bal("22:8", "الثوب الواسع فوق الثياب", "غطاء الرأس الصغير", "النعل الذي يُلبس في القدم", "الحزام الذي يُشدّ على الوسط");
bal("22:10", "سؤال أم سلمة عن ذكر النساء", "سؤال الصحابيات عن الميراث", "خروج النساء للغزو مع الرجال", "بيعة النساء للنبي ﷺ يوم الفتح");
bal("22:11", "وليمة زواجه ﷺ بزينب", "فتح مكة ودخول البيوت", "قدوم وفد ثقيف إلى المدينة", "حادثة الإفك وما تبعها");
bal("22:12", "ما أرى ربك إلا يسارع في هواك", "حسبنا الله ونعم الوكيل", "سمعنا وأطعنا غفرانك ربنا", "الحمد لله الذي برّأني");
bal("22:13", "الطباق والمقابلة", "الجناس التام بين الألفاظ", "السجع وحده دون معنى", "الالتفات من الغيبة إلى الخطاب");
bal("22:14", "تشبيه بليغ", "استعارة مكنية", "مجاز عقلي", "كناية عن الشجاعة والإقدام");
bal("22:15", "الحِمل الثقيل", "الثوب الواسع", "الطريق الوعر", "السلاح والعتاد");
bal("22:17", "افتقار الخلق إلى الله وغناه عنهم", "أن الفقر عيب يُذمّ به صاحبه", "أن الأغنياء لا يحتاجون إلى الله", "وجوب الزكاة على الأغنياء فقط");
bal("22:18", "شكر آل داود وكفر أهل سبأ", "قوة قوم عاد وضعف قوم ثمود", "غنى قارون وفقر موسى عليه السلام", "حكمة لقمان وجهل قومه");
bal("22:20", "الصلاة والسلام على النبي ﷺ", "طاعة الأمراء وولاة الأمور", "قيام الليل وقراءة القرآن", "الإنفاق في سبيل الله");
bal("22:24", "عِظم أمانة التكليف بعد كثرة الأحكام", "لا مناسبة بين الخاتمة وموضوع السورة", "لأن السورة كلها عن حفظ المال", "لأنها قصة مستقلة عن بقية السورة");
bal("22:25", "دعاء بطر، أو خبر شكوى", "لا فرق بين القراءتين", "كلها خبر عن حالهم", "كلها أمر موجّه للملائكة");
bal("22:26", "يصلي الله عليه بها عشرًا", "تعدل أجر حجة مبرورة", "تكفّر الكبائر كلها بلا توبة", "لا فضل خاص لها");
bal("22:28", "ختم النبوة", "تعدد الأنبياء بعده ﷺ", "أن النبوة تُكتسب بالعبادة", "أن الأولياء الصالحين أنبياء");
bal("22:29", "حجية أفعال النبي ﷺ", "حجية القياس على الأصل", "حجية إجماع العلماء", "حجية العرف والعادة");
bal("22:30", "معاداة الشيطان بالحذر ومخالفته", "مصالحة الشيطان واتقاء شره", "إهمال وسوسته وعدم الالتفات", "الخوف منه دون عمل أو ذكر");
bal("22:31", "الجلالة مفعول مقدّم، والعلماء فاعل", "الجلالة فاعل، والعلماء مفعول به", "كلاهما مبتدأ وخبر", "الجلالة بدل، والعلماء نائب فاعل");

// ======================= الجزء 21 =======================
bal("21:0", "لا تُمِل وجهك تكبّرًا", "لا تضع خدّك على الأرض", "لا تضحك بصوت عالٍ", "لا تُطِل النظر إلى الناس");
bal("21:2", "غلبة الفرس للروم وبشارة بانتصارهم", "انتصار المسلمين على الروم في مؤتة", "إسلام هرقل ملك الروم", "رحلة قريش في الشتاء والصيف");
bal("21:3", "زيد بن حارثة", "أسامة بن زيد بن حارثة", "علي بن أبي طالب", "أنس بن مالك الأنصاري");
bal("21:4", "كناية عن شدة الخوف", "وصف حقيقي لمرض أصابهم", "كناية عن الفرح بالنصر", "تشبيه للقلوب بالطيور");
bal("21:6", "لتحزّب الأعداء على المدينة", "لكثرة أحزاب المنافقين داخل المدينة", "لذكر أحزاب الأنبياء وأتباعهم", "لأنها مقسّمة إلى أحزاب كثيرة");
bal("21:8", "بطرًا وخيلاء", "بسرعة وعجلة", "بفرح مشروع", "حافيًا متواضعًا");
bal("21:10", "سعد بن أبي وقاص", "أبو بكر الصديق", "مصعب بن عمير العبدري", "عمار بن ياسر العنسي");
bal("21:11", "أنس بن النضر", "حمزة بن عبد المطلب", "مصعب بن عمير", "سعد بن معاذ");
bal("21:12", "الطباق", "الجناس التام", "التورية", "السجع");
bal("21:13", "مجاز مرسل علاقته الآلية", "استعارة تصريحية", "تشبيه بليغ", "لا مجاز في التعبير");
bal("21:14", "أن كلمات الله لا تنفد", "الحث على الكتابة والتدوين", "وصف البحار وكثرة مائها", "بيان عدد الأشجار في الأرض");
bal("21:15", "السكن والمودة والرحمة", "المال والجاه والنسب", "كثرة العدد فقط", "التفاخر بين القبائل");
bal("21:17", "غزوة الأحزاب", "فتح مكة", "حجة الوداع", "الهجرة إلى المدينة");
bal("21:20", "الحكمة", "أحكام الميراث وتقسيم التركات", "قصص الأمم الهالكة وعقوباتها", "أحكام القتال والغنائم");
bal("21:21", "عرض أدلة القدرة والوحدانية والبعث", "التسلية بقصص الأمم السابقة", "بيان الأحكام الفقهية بالتفصيل", "الرد على شبهات أهل الكتاب");
bal("21:25", "حق الوالدين بعد حق الله، ولا طاعة في الشرك", "قطع للكلام بلا سبب ولا مناسبة", "أنها من كلام لقمان لابنه أيضًا", "بيان أحكام الميراث بين الآباء والأبناء");
bal("21:26", "الكسر: العلماء، والفتح: الخلق", "لا فرق في المعنى بين القراءتين", "بالكسر: الملائكة المقرّبون خاصة", "بالفتح: العلماء من أهل الكتاب");
bal("21:27", "بالشرك", "بظلم الناس في أموالهم", "بالمعاصي والذنوب كلها", "بالكذب وشهادة الزور");
bal("21:28", "حولان كاملان", "سنة واحدة", "ثلاث سنوات", "لا حدّ له");
bal("21:29", "القادر على البدء أقدر على الإعادة", "رؤية الموتى يعودون في الدنيا", "أقوال الكهان والعرّافين", "لا دليل في الآية على البعث");
bal("21:30", "الاحترام وتحريم النكاح", "كل الأحكام بلا استثناء", "الميراث والولاية فقط", "النفقة والخلوة");
bal("21:31", "فضل قيام الليل", "ذمّ النوم مطلقًا", "السهر في أمور الدنيا", "ترك الدعاء والاكتفاء بالذكر");

// ======================= الجزء 20 =======================
bal("20:0", "ضربه بجُمع كفّه", "طعنه بسيف", "دفعه في البحر", "شتمه وسبّه");
bal("20:2", "أبو طالب", "أبو لهب", "الوليد بن المغيرة", "عتبة بن ربيعة");
bal("20:3", "الوهن والضعف", "الإتقان والجمال", "الكثرة والانتشار", "العلوّ والارتفاع");
bal("20:4", "ابتلاء المؤمنين", "أن الإيمان يكفي فيه القول باللسان", "أن المؤمن لا يُصاب بأذى في الدنيا", "أن الفتنة خاصة بالكافرين وحدهم");
bal("20:5", "لمن لا يريد علوًّا ولا فسادًا", "لأصحاب الأموال والتجارات", "لأهل السلطان والجاه", "لكل من آمن ولو أفسد في الأرض");
bal("20:6", "قصة موسى عليه السلام", "قصة يوسف عليه السلام وإخوته", "قصة نوح عليه السلام والطوفان", "قصة أصحاب الكهف والرقيم");
bal("20:8", "ينتظر الطلب ويتلفّت", "يمشي ببطء وتأنٍّ", "ينظر إلى السماء داعيًا", "يبكي على ما فعل");
bal("20:13", "استعارة", "تشبيه بليغ", "كناية عن الحزن", "طباق");
bal("20:14", "سرعة الحركة والاهتزاز", "الحجم الصغير", "اللون الأسود", "الصوت والفحيح");
bal("20:15", "أنها الحياة الكاملة الدائمة", "الدواب والأنعام في الجنة", "الحيوانات المفترسة في النار", "قِصر الآخرة بالنسبة إلى الدنيا");
bal("20:16", "أن الصلاة المقامة تنهى عن المنكر", "أن الصلاة تكفي عن سائر العبادات", "أن المصلي لا يخطئ أبدًا", "أن الصلاة مشروعة لأجل الصحة");
bal("20:17", "نسب النعمة إلى علمه", "أنه أنفق ماله كله في الخير", "أنه تعلّم التجارة من موسى", "أنه أطاع موسى وترك فرعون");
bal("20:18", "إقامة الحجة على التوحيد", "السؤال الحقيقي عن عدد الآلهة", "مدح المشركين على تفكيرهم", "بيان أحكام العبادة والصلاة");
bal("20:19", "لمثل العنكبوت في وهن الشرك", "لكثرة العناكب في مكة آنذاك", "لقصة نسج العنكبوت على الغار", "لأنها تتحدث عن الحشرات");
bal("20:20", "التمكين للمستضعفين", "إهلاك الملوك جميعًا في الدنيا", "كثرة المال والولد للمؤمنين", "الهجرة من مكة إلى مصر");
bal("20:24", "ردّ موسى منتصرًا، وردّ النبي ﷺ إلى مكة", "لا مناسبة بين الخاتمة وقصة موسى", "لذكر الحج ومناسكه في الخاتمة", "لذكر فرعون وهلاكه في آخرها");
bal("20:25", "تتابع علمهم أو عجز عن معرفتها", "علموا أمر الآخرة علم يقين", "ماتوا قبل أن يدركوا الآخرة", "لا معنى لهذه القراءة");
bal("20:26", "الأنبياء ثم الأمثل فالأمثل", "الأغنياء وأصحاب الأموال", "الملوك وأصحاب السلطان", "الكفار والمعاندون");
bal("20:27", "عرض الولي موليّته وجعل المنفعة مهرًا", "تحريم المهر في النكاح", "منع الإجارة على العمل", "وجوب الزواج باثنتين");
bal("20:28", "انفراد الله بعلم الغيب", "أن الملائكة تعلم الغيب كله", "أن الأولياء يعلمون الغيب", "أن النجوم تخبر بالغيب");
bal("20:29", "شرع من قبلنا", "النسخ قبل التمكن من الفعل", "حجية الإجماع", "الاستحسان");
bal("20:30", "التوسل بإظهار الفقر إلى الله", "طلب المال صراحة من الناس", "الشكوى للناس من الحال", "الاعتماد على النفس والقوة");

