bal("19:3", "تشبيه بليغ", "كناية عن الكرم والعطاء", "استعارة مكنية للأرض", "طباق سلب بين العمل وعدمه");
bal("19:5", "المؤمنون الذاكرون المنتصرون للحق", "شعراء المدح والثناء فقط", "شعراء الجاهلية قبل الإسلام", "لم يستثنِ الله منهم أحدًا");
bal("19:8", "معينًا على معصية ربه", "ظاهرًا مكشوفًا للناس", "قويًّا شديد البأس", "راكبًا على دابته");
bal("19:10", "سؤال ابن مسعود عن أعظم الذنوب", "سؤال الصحابة عن مناسك الحج", "خصومة بين رجلين في المسجد", "سؤال المشركين عن مصير آبائهم");
bal("19:11", "عقبة بن أبي معيط", "أبو طالب عمّ النبي ﷺ", "الوليد بن المغيرة المخزومي", "عبد الله بن أبي بن سلول");
bal("19:13", "شدة الندم", "الجوع الشديد", "الغضب على الناس", "الألم الجسدي");
bal("19:14", "الإضراب والترقّي", "النفي المجرد", "الاستدراك على المدح", "العطف المجرد بلا معنى زائد");
bal("19:15", "الذكر الحسن والثناء", "اللسان الفصيح البليغ", "الصدق في الكلام فقط", "تعلّم اللغات وإتقانها");
bal("19:16", "السالم من الشرك والشك", "القلب الصحيح من الأمراض", "القلب الذي لا يحزن أبدًا", "القلب الكثير الذكاء والفطنة");
bal("19:17", "نسب النعمة إلى فضل الله", "افتخر بقوة جنوده وملكه", "نسب الفضل إلى العفريت", "أمر بتحطيم العرش وإحراقه");
bal("19:20", "بالدعاء بصلاح الأزواج والذرية", "بالمشي على الأرض هونًا", "بقيام الليل سجدًا وقيامًا", "بترك الإسراف والتقتير في النفقة");
bal("19:23", "الشعراء", "الأعراف", "الأنعام", "يوسف");
bal("19:24", "نفي أن يكون القرآن شعرًا أو كهانة", "مدح الشعر وبيان منزلته", "بيان أوزان الشعر وبحوره", "لا مناسبة بين الختام وموضوع السورة");
bal("19:25", "حاذقين / أشِرين", "لا فرق بين القراءتين", "كلتاهما بمعنى: خائفين", "كلتاهما بمعنى: فقراء");
bal("19:26", "إن لك مكان كل سيئة حسنة", "لا مغفرة لك على ما قدّمت", "اذهب بذنوبك إلى النار", "أعِد عملك من جديد");
bal("19:27", "التوسط", "وجوب إنفاق المال كله", "تحريم الادخار مطلقًا", "أن الإمساك أفضل من الإنفاق");
bal("19:28", "الاستدلال بالربوبية على الألوهية", "إثبات الشفاعة للأصنام", "إثبات تعدد الآلهة", "نفي مشروعية الدعاء");
bal("19:29", "لا، وإنما خُصّوا للاهتمام", "نعم، الإنذار خاص بالأقربين", "نعم، لأن المفهوم حجة هنا", "الآية منسوخة بآيات أخرى");
bal("19:30", "الإعراض عن السفهاء", "مجادلة الجاهلين حتى يقتنعوا", "مقابلة السبّ بمثله", "ترك السلام على الناس");

