bal("18:13", "نور الله في قلب المؤمن", "نور الشمس في النهار", "نور القمر ليلة البدر", "نور المساجد فقط");
bal("18:14", "استعارة", "تشبيه تام", "كناية عن الكرم", "طباق");
bal("18:15", "المجتهدون الخائفون ألا يُقبل منهم", "العصاة الذين يخافون العقوبة", "المتصدقون رياءً وسمعة", "الذين لا يعملون شيئًا من الطاعات");
bal("18:16", "حسن الظن ورفض الإشاعة", "نقل الأخبار بسرعة للتحذير", "السكوت عن الظالم حتى يتبيّن", "سوء الظن احتياطًا للدين");
bal("18:17", "من لا زوج له", "الأرامل من النساء فقط", "الأيتام الصغار", "كبار السن من الرجال");
bal("18:18", "افتُتحت بلفظ «سورة»", "افتُتحت بالحروف المقطّعة", "افتُتحت بالقسم بالنور", "افتُتحت بالنداء للمؤمنين");
bal("18:19", "فلاح المؤمنين ونفيه عن الكافرين", "بدأت بالقصص وختمت بالأحكام", "لا تناسب بين أولها وآخرها", "بدأت بالدعاء وختمت به فقط");
bal("18:20", "من آية النور", "من نور الشمس", "من قصة موسى والنار", "من صلاة الفجر");
bal("18:23", "بني المصطلق", "بدر الكبرى", "تبوك", "خيبر");
bal("18:24", "سدّ ذرائع الفاحشة والقذف", "لا مناسبة بين الموضعين", "بيان أحكام الصيام والاعتكاف", "لأن هذه الآيات نزلت في الحج");
bal("18:25", "الجمع للتنوع، والإفراد للجنس", "لا فائدة من اختلاف القراءتين", "الإفراد للأمانات المالية فقط", "الجمع للودائع دون العهود");
bal("18:26", "شققن مروطهن فاختمرن بها", "تأخّرن في الامتثال أيامًا", "سألن النبي ﷺ عن معناها", "خرجن إلى المسجد متحجّبات");
bal("18:27", "ثمانون جلدة ورد الشهادة", "مائة جلدة وتغريب عام", "النفي من البلد سنة كاملة", "لا عقوبة دنيوية عليه");
bal("18:28", "أن للخلق حكمة، والبعث حق", "أن الخلق بلا غاية ولا حكمة", "أن الموت نهاية كل شيء", "أن الإنسان مخيّر بلا حساب");
bal("18:29", "الاستثناء بعد جمل متعاطفة", "النسخ", "القياس", "الإجماع");
bal("18:30", "العفو سبب للمغفرة", "الانتقام أولى من العفو", "قطع الإحسان عن المسيء", "لا علاقة بين العفو والمغفرة");

// ======================= الجزء 17 =======================
bal("17:0", "الصحيفة", "الجبل العظيم", "السحاب الكثيف", "الثوب الواسع");
bal("17:2", "المتبارزون يوم بدر", "موسى وفرعون", "المهاجرون والأنصار", "أهل الكتاب والمشركون");
bal("17:3", "أن العمى الحقيقي عمى البصيرة", "أن القلوب في الرؤوس لا في الصدور", "فضل البصر على السمع", "أن العمى لا علاج له");
bal("17:4", "أول آية في الإذن بالقتال", "آخر آية نزلت من القرآن", "أول آية في فرض الصيام", "أول آية في فرض الزكاة");
bal("17:5", "التعريض بالحاجة مع الثناء", "الإلحاح بالشكوى للناس", "الاعتراض على القضاء والقدر", "طلب المال والولد صراحة");
bal("17:8", "يونس عليه السلام", "نوح عليه السلام", "ذو القرنين", "إلياس عليه السلام");
bal("17:10", "من يعبد الله على شكّ وتقلّب", "من يعبد الله سرًّا خوفًا من قومه", "من يقرأ القرآن بحرف واحد فقط", "من يصلي على طرف المسجد");
bal("17:11", "اعتراضهم بعيسى والملائكة", "سؤال الصحابة عن نعيم الجنة", "جدال اليهود في يوم السبت", "طلب المشركين معجزة حسية");
bal("17:12", "في سفر", "في غار حراء", "في المسجد الحرام", "في بيت عائشة");
bal("17:13", "تشبيه بليغ", "استعارة تمثيلية", "كناية عن الكرم", "طباق");
bal("17:14", "استعارة", "تشبيه مرسل", "مجاز مرسل", "جناس");
bal("17:15", "هلاك المشرك وضياعه", "رحلة في الفضاء الواسع", "سقوط الشهب من السماء", "صيد الطيور الجارحة");
bal("17:16", "أن المقصود التقوى لا اللحم", "أن الذبح غير مشروع أصلًا", "أن اللحم يُرسل إلى السماء", "أن العبرة بكثرة الذبائح");
bal("17:17", "تفهيم سليمان مع الثناء عليهما", "أن داود أخطأ فذُمّ على حكمه", "أن سليمان عصى أباه في القضاء", "أن القضاء لا يحتاج إلى علم");
bal("17:18", "لذكر أذان إبراهيم بالحج", "لأنها نزلت في موسم الحج", "لأنها تُقرأ في أيام الحج", "لذكر حجة الوداع فيها");
bal("17:19", "التحذير من الغفلة", "الأمر بالقتال والجهاد", "تعداد النعم على العباد", "قصة آدم وإبليس");
bal("17:22", "﴿أُذن للذين يُقاتَلون﴾", "﴿يا أيها الناس اتقوا ربكم﴾", "﴿ومن الناس من يجادل في الله﴾", "﴿فإنها لا تعمى الأبصار﴾");
bal("17:23", "من أوائل ما نزل وأجوده", "من آخر ما نزل من القرآن", "أنها نزلت كلها في المدينة", "أنها قصيرة سهلة الحفظ");
bal("17:24", "التخويف من الساعة ثم الأمر بالاستعداد", "لا مناسبة بين أول السورة وآخرها", "أولها وآخرها قصص عن الأنبياء", "أولها وآخرها أحكام للحج فقط");
bal("17:25", "خبر عنه، أو أمر له", "لا فرق بين القراءتين", "«قل» خطاب للملائكة", "«قال» خبر عن موسى");
bal("17:26", "لا يدعو بها مسلم إلا استُجيب له", "تعدل ثلث القرآن في الأجر", "تُقال في الصلاة فقط", "لا فضل خاص لها");
bal("17:27", "الأكل منها والتصدق", "تحريم الأكل منها", "وجوب بيعها وإنفاق ثمنها", "إعطاؤها للأغنياء فقط");
bal("17:28", "دليل التمانع", "دليل الفطرة وحده", "دليل النقل وحده", "لا دليل عقلي في الآية");
bal("17:29", "سؤال العامي لأهل العلم", "تحريم السؤال عما لا يُعلم", "وجوب الاجتهاد على كل أحد", "ترك العلم لأهل الاختصاص");
bal("17:30", "المسارعة في الخيرات والدعاء والخشوع", "كثرة المال والولد", "شرف النسب والقبيلة", "طول العمر في الطاعة");

// ======================= الجزء 16 =======================
bal("16:0", "جدولًا صغيرًا", "سريرًا تجلس عليه", "شجرة نخل مثمرة", "سرًّا مكتومًا");
bal("16:2", "استبطاء النبي ﷺ زيارة جبريل", "سؤال اليهود عن الملائكة", "استبطاء المشركين نزول العذاب", "سؤال الصحابة عن موعد الساعة");
bal("16:3", "استعارة", "تشبيه مرسل", "كناية عن الشجاعة", "طباق");
bal("16:4", "ثلاث مرات", "مرتين", "أربع مرات", "مرة واحدة");
bal("16:5", "لم ينزل القرآن لإشقائك بل تذكرة", "نزل القرآن ليشقى به الكافرون فقط", "القرآن لا يُتعب قارئه أبدًا", "نهي النبي ﷺ عن قيام الليل");
bal("16:6", "ردمًا يحجز يأجوج ومأجوج", "مسجدًا على أهل الكهف", "قصرًا من زجاج", "سفينة عظيمة");
bal("16:10", "العاص بن وائل", "أبو جهل بن هشام", "الوليد بن المغيرة", "أمية بن خلف");
bal("16:12", "استعارة", "تشبيه بليغ", "كناية عن الهدوء", "طباق");
bal("16:13", "أن كلمات الله لا تنتهي", "وصف ماء البحر وسعته", "الحث على الكتابة والتدوين", "بيان حجم البحار وأعماقها");
bal("16:14", "مجاز مرسل", "استعارة مكنية", "تشبيه بليغ", "لا مجاز فيه");
bal("16:15", "أن صلاح الآباء ينفع الأبناء", "أن الكنوز تُدفن تحت الجدران", "أن اليتيم لا يرث من أبيه", "ذمّ ادّخار المال للأبناء");
bal("16:16", "ليشدّ به أزره", "ليرث ملكه من بعده", "لأنه أكبر منه سنًّا فقط", "ليبقى في مصر بدلًا منه");
bal("16:18", "قصة موسى عليه السلام", "قصة يوسف عليه السلام", "قصة إبراهيم عليه السلام", "قصة سليمان عليه السلام");
bal("16:19", "العصمة من الدجال", "دخول الجنة بلا حساب", "قضاء الدين وسعة الرزق", "الشفاء من الأمراض");
bal("16:23", "قول المشركين: أُنزل عليه ليشقى", "سؤال اليهود عن قصة موسى", "قول المنافقين في الجهاد", "سؤال الصحابة عن قيام الليل");
bal("16:24", "هبة الولد للعباد وتنزيه الله عنه", "لا مناسبة بين أولها وخاتمتها", "لأن السورة كلها عن الميراث", "لأن السورة نزلت في الهجرة");
bal("16:25", "حفص: «إنْ هذان»، وأبو عمرو: «إنّ هذين»", "كلاهما «إنّ هذان» بالتشديد", "كلاهما «إنّ هذين» بالياء", "لا خلاف بين القراء فيها");
bal("16:26", "يرحم الله موسى، لوددنا لو صبر", "لقد أخطأ موسى في اعتراضه", "لقد أخطأ الخضر في أفعاله", "لا تسألوا عن هذه القصة");
bal("16:27", "قضاء الصلاة المنسية عند تذكّرها", "تحريم الصلاة عند النوم", "سقوط الصلاة الفائتة", "جواز تأخير الصلاة عمدًا");
bal("16:28", "الاستواء معلوم والكيف مجهول", "تأويل الاستواء بالاستيلاء", "تشبيه استواء الله بالمخلوق", "التوقف عن الإيمان بالصفة");
bal("16:29", "لا؛ هو منسوخ في شرعنا", "نعم، مستحب لمن أراده", "نعم، واجب في رمضان", "مباح في كل وقت");
bal("16:30", "موافقة الشرع والإخلاص", "الكثرة والسرعة في العمل", "الشهرة والقبول عند الناس", "المال والجاه");

// ======================= الجزء 15 =======================
bal("15:0", "لوح كُتبت فيه أسماؤهم", "اسم كلبهم الذي رافقهم", "الملك الظالم في زمانهم", "الطعام الذي حملوه معهم");
bal("15:3", "استعارة", "تشبيه تام الأركان", "مجاز مرسل علاقته السببية", "جناس ناقص");
bal("15:4", "البخل والإسراف", "الأسر والحرية", "القتال والسلم بين القبائل", "المرض والصحة");
bal("15:5", "تعليق المستقبل بمشيئة الله", "ترك التخطيط للمستقبل كليًّا", "عدم الوعد بأي شيء مطلقًا", "تأجيل الأعمال إلى الغد دائمًا");
bal("15:6", "قصة يوسف", "قصة أصحاب الكهف", "قصة صاحب الجنتين", "قصة ذي القرنين");
bal("15:10", "سبّ المشركين للقرآن إذا جهر به", "كثرة الكلام في المسجد النبوي", "خلاف الصحابة في صيغة الأذان", "سؤال عن صلاة المسافر");
bal("15:11", "إنس عبدوا جنًّا فأسلم الجن", "أهل الكتاب من اليهود والنصارى", "عبدة الأصنام في الطائف", "المجوس عبدة النار");
bal("15:12", "طلب الكبراء مجلسًا دون الفقراء", "ما جرى في غزوة بدر الكبرى", "مفاوضات صلح الحديبية", "الهجرة إلى الحبشة");
bal("15:13", "عمله المكتوب عليه", "طائر حقيقي يرافقه", "رزقه المقسوم له", "قلادة تُعلّق في عنقه");
bal("15:14", "التهكم بالمتكبر", "المدح والثناء على المشي", "الترغيب في الرياضة", "الدعاء للماشي");
bal("15:15", "للطريقة الأعدل والأصوب", "للطريق الأقصر إلى مكة", "لأقوم الناس جسمًا", "للقيام في الصلاة فقط");
bal("15:16", "لأن النهي عن القرب أبلغ", "لأن الزنا مكروه لا محرم", "لتخفيف الحكم على الناس", "لا فرق بين العبارتين");
bal("15:17", "يوم فتح مكة", "يوم بدر حين التقى الجمعان", "في طريق الهجرة إلى المدينة", "يوم أحد بعد الهزيمة");
bal("15:18", "تنزيهًا لله عن العجز", "لأنها نزلت أثناء الصلاة", "للتعجب من عناد المشركين", "لا مناسبة خاصة لذلك");
bal("15:19", "الإحسان إلى الوالدين", "الجهاد في سبيل الله", "صيام الأيام البيض", "الزكاة والصدقات");
bal("15:22", "في المدينة، سأله اليهود", "في مكة، سأله أبو جهل وأصحابه", "في الطائف، سأله أهلها", "في الحبشة، سأله النجاشي");
bal("15:24", "خُتمت الإسراء بالحمد وافتُتحت به الكهف", "لا مناسبة بين السورتين", "كلتاهما تقصّان قصة موسى فقط", "كلتاهما من السور المدنية");
bal("15:25", "إسناد إلى الوالدين ثم إبدال", "خطأ في القراءة لا وجه له", "الضمير يعود على الأبناء", "الضمير يعود على الأجداد");
bal("15:26", "الشفاعة العظمى", "دخول مكة فاتحًا", "رحلة الإسراء والمعراج", "إمامة الأنبياء في الصلاة");
bal("15:27", "أوقات الصلوات الخمس", "أحكام صلاة العيدين", "صفة صلاة الكسوف والخسوف", "قيام الليل فقط");
bal("15:28", "أنه بالروح والجسد", "أنه كان رؤيا منام", "أنه كان بالروح وحدها", "أنه كان لنبي غيره");
bal("15:29", "لا عقاب قبل بلوغ الرسالة", "العقل وحده يوجب العقاب", "يجوز العذاب بلا حجة", "لا حساب ولا عقاب أبدًا");
bal("15:30", "اختيار أحسن الكلام", "الصراحة الجارحة في النصح", "كثرة الجدال لإظهار الحق", "الصمت الدائم عن كل كلام");
bal("15:31", "مفعول مطلق", "مبتدأ مرفوع", "فاعل مرفوع", "حال منصوبة");

// ======================= الجزء 14 =======================
bal("14:2", "عمار بن ياسر", "بلال بن رباح", "خبّاب بن الأرت", "صهيب الرومي");
bal("14:3", "استعارة: الجوع يشملهم كاللباس", "خطأ في اللفظ يصححه السياق", "تشبيه تام الأركان", "سجع بين الكلمتين");
bal("14:4", "حفظ القرآن من التحريف", "حفظ الكتب السماوية السابقة كلها", "وجوب حفظ القرآن على كل مسلم", "حفظ الناس من الشياطين");
bal("14:5", "الحكمة ثم الموعظة ثم الجدال بالأحسن", "القوة ثم الترغيب ثم الترهيب", "الصمت ثم الكلام ثم الهجر", "الكتابة ثم الخطابة ثم الشعر");
bal("14:6", "سورة النِّعَم", "سورة الرحمة", "سورة الشفاء", "سورة العسل");
bal("14:8", "اجهر", "اسكت", "اهرب", "اكتب");
bal("14:10", "رؤوس من قريش", "يهود المدينة", "المنافقون في المدينة", "أهل الطائف وثقيف");
bal("14:11", "التمثيل بحمزة يوم أحد", "فتح مكة وعفو النبي ﷺ عن أهلها", "أسرى غزوة بدر الكبرى", "تعذيب عمار بن ياسر");
bal("14:12", "بأن لسانه أعجمي والقرآن عربي", "بإهلاك الغلام وصاحبه", "بأمر النبي ﷺ بالهجرة", "بالسكوت عنهم وترك الرد");
bal("14:13", "ناقض العهد", "تارك العمل الصالح", "مبذّر المال في الباطل", "قاطع الرحم");
bal("14:15", "الفرق بين الأصنام والله", "أحكام الرقيق وبيعهم", "فضل التجارة على الزراعة", "حال الفقير والغني في الدنيا");
bal("14:16", "الإلهام", "الوحي بواسطة جبريل", "الرؤيا في المنام", "الكتابة في الألواح");
bal("14:17", "أجمع آية للخير والشر", "أعظم آية في كتاب الله", "آخر آية نزلت من القرآن", "أطول آية في المصحف");
bal("14:19", "إمامًا جامعًا للخير", "شعبًا كبيرًا من الناس", "كثير الأولاد والذرية", "زمنًا طويلًا من الدهر");
bal("14:23", "من ﴿وإن عاقبتم﴾ إلى آخرها", "الآيات العشر الأولى منها", "الآيات التي تذكر النحل والعسل", "آية الوحي إلى النحل وحدها");
bal("14:24", "الاستعجال أولها والصبر آخرها", "لا مناسبة بين أولها وآخرها", "كلاهما في وصف العسل وفوائده", "كلاهما في مناسك الحج");
bal("14:25", "إسناد إلى الله أو إلى الملائكة", "تناقض بين القراءتين في المعنى", "«تنزل» هنا للمطر لا للملائكة", "لا فرق بينهما في اللفظ");
bal("14:26", "القناعة والرزق الحلال", "كثرة المال والولد", "الملك والسلطان", "طول العمر فقط");
bal("14:27", "الضرورات تبيح المحظورات", "الحرام لا يباح بحال أبدًا", "الأكل من الميتة مباح مطلقًا", "لا رخصة في الشريعة");
bal("14:28", "عبادة الله واجتناب الطاغوت", "بناء المساجد", "الجهاد فقط", "الزهد في الدنيا");
bal("14:29", "مبيّنة له", "مستغنى عنها بالقرآن", "معارضة لأحكام القرآن", "لا علاقة بينهما");
bal("14:30", "الإكثار من الشكر", "أن إحصاء النعم ممكن لمن اجتهد", "أن النعم قليلة يسهل عدّها", "لا حاجة للشكر مع كثرة النعم");

