bal("13:0", "قليلة رديئة", "كثيرة جيدة", "ثمينة نادرة الوجود", "مسروقة من مصر");
bal("13:2", "أهل القرية", "جدران القرية وبيوتها حقيقة", "قرية النمل المذكورة", "القرية التي وُلد فيها يوسف");
bal("13:3", "الماء: الحق، والزبد: الباطل", "الماء: الدنيا، والزبد: الآخرة", "الماء: المطر، والزبد: الملح", "الماء: العلم، والزبد: المال");
bal("13:4", "تغيّر النعم بتغيّر الأعمال", "أن الأحوال لا علاقة لها بالأعمال", "أن الله لا يغيّر شيئًا أبدًا", "أن التغيير يحصل بالأماني");
bal("13:5", "شهادة التوحيد", "الكلام اللين مع الناس", "الصدقة الخفية", "الدعاء في السجود");
bal("13:6", "الاعتبار لأولي الألباب", "التسلية والترفيه عن السامع", "معرفة تاريخ مصر القديم", "بيان أحكام تفسير الرؤى");
bal("13:8", "ممتلئ حزنًا يكتمه", "غاضب يصرخ في وجوههم", "نائم لا يدري بما حوله", "فرِح بلقاء أبنائه");
bal("13:10", "سؤال القبر", "الهجرة إلى المدينة", "غزوة بدر الكبرى", "فرض الصيام");
bal("13:12", "طلب المشركين تسيير الجبال", "سؤال اليهود عن الروح", "زلزلة وقعت في المدينة", "طلب الأنصار نزول المطر");
bal("13:13", "إنكارهم اسم «الرحمن»", "إنكار اليهود للبعث والحساب", "إنكار المشركين وجود الملائكة", "سؤالهم عن معنى الرحمة");
bal("13:14", "برماد عصفت به الريح", "بجبل راسخ لا يتزحزح", "بماء جارٍ في الوادي", "بشجرة مثمرة في البستان");
bal("13:15", "لا أصل لها ولا ثبات", "كثرة ثمرها وظلها", "طولها وارتفاعها", "كثرة شوكها");
bal("13:16", "الحصر", "التأكيد على الصلاة فقط", "الترتيب الزمني للأحداث", "لا فائدة من التقديم");
bal("13:17", "الشكر يزيد النعم", "النعم تزيد مطلقًا بلا سبب", "الشكر باللسان يكفي وحده", "لا علاقة بين الشكر والنعم");
bal("13:18", "من تسبيح الرعد", "من غزوة وقعت في المطر", "من قصة نوح والطوفان", "من صوت الصيحة على ثمود");
bal("13:20", "لطيف لما يشاء", "شديد العقاب", "سريع الحساب", "ذو انتقام");
bal("13:24", "ختام يوسف وافتتاح الرعد بقلة المؤمنين", "لا مناسبة بين السورتين", "كلتاهما في الأحكام الفقهية", "كلتاهما من السور المدنية");
bal("13:25", "أيقن الرسل تكذيب أقوامهم", "أن الرسل كذبوا على أقوامهم", "أن الملائكة كذبت على الرسل", "لا معنى للتشديد هنا");
bal("13:26", "النخلة", "الزيتونة", "التينة", "الكرمة");
bal("13:27", "الجعالة والكفالة", "تحريم الجوائز والمكافآت", "تحريم السفر بالتجارة", "وجوب الصدقة على المسافر");
bal("13:28", "لا سلطان له إلا الوسوسة", "أن الشيطان يجبر الناس على المعصية", "أن الشيطان يملك الضر والنفع", "أن العبد غير مسؤول عن عمله");
bal("13:29", "يُفهم بلسان العرب", "أن القرآن لا يُفهم أصلًا", "أن اللغة لا أثر لها في الفهم", "أن الترجمة كافية لفهمه");
bal("13:30", "التقوى والصبر", "الذكاء والحيلة طريق النجاح", "الانتقام من الظالم", "الحظ والصدفة");
bal("13:31", "خبر لمبتدأ محذوف", "فاعل مرفوع", "مفعول به منصوب", "حال منصوبة");

// ======================= الجزء 12 =======================
bal("12:0", "مشويّ", "نيِّء لم يُطبخ", "صغير السن", "مطبوخ بالماء");
bal("12:2", "رجل أصاب قُبلة فندم", "ترك بعض الصحابة صلاة الفجر", "سؤال عن مواقيت الصلاة", "تأخّر الصحابة عن الجماعة");
bal("12:3", "استعارة مع إيجاز بديع", "طول عباراتها وكثرة ألفاظها", "كثرة الجناس فيها", "خلوّها من الأفعال");
bal("12:4", "ليس من الناجين لكفره", "ليس ابنك من النسب", "ليس من قومك وعشيرتك", "ليس من سكان بلدك");
bal("12:5", "إخوته وأبواه", "الملوك والعزيز", "أصحابه في السجن", "سنوات القحط");
bal("12:6", "لأهوال القيامة وهلاك الأمم", "لطولها وكثرة آياتها", "لكثرة الأحكام الفقهية فيها", "لأنها نزلت في كِبَره");
bal("12:8", "هلمّ", "اخرج من هنا", "انتظر قليلًا", "اسكت");
bal("12:11", "تعنّت المشركين", "قلة الطعام في مكة", "طول الطريق في الهجرة", "مرضه ﷺ");
bal("12:12", "بالجبال", "بالسحاب المتراكم", "بالخيل المسرعة", "بالنار المشتعلة");
bal("12:13", "للمبالغة", "خطأ في اللفظ", "لأنه دم حيوان", "لمراعاة السجع");
bal("12:14", "قصر مع تشبيه", "استفهام إنكاري", "طباق بين الحُسن والقُبح", "دعاء على يوسف");
bal("12:15", "إيثار البلاء على المعصية", "حبّ السجن لذاته", "ضعف يوسف أمام الفتنة", "عدم الثقة بالله");
bal("12:16", "التطفيف", "عبادة النار", "وأد البنات", "الربا فقط");
bal("12:17", "لتنوّع العبر وحسن العاقبة", "لأنها أطول قصة في القرآن", "لأنها عن ملك من الملوك", "لأنها خالية من الأحزان");
bal("12:19", "الاستقامة بلا غلو ولا تقصير", "الهجرة إلى المدينة", "الجهاد في سبيل الله", "طلب العلم والرحلة فيه");
bal("12:21", "مكة قبل الهجرة", "بعد فتح مكة", "بعد غزوة بدر", "في حجة الوداع");
bal("12:23", "من سأل عن قصة يوسف", "إخوة يوسف الأحد عشر", "أهل مصر في زمانه", "الصحابة عن أحكام الصلاة");
bal("12:24", "تحذير المخاطَبين", "بيان التاريخ فقط دون عبرة", "لا مناسبة بين القصص والتعقيب", "مدح الأمم الهالكة");
bal("12:25", "إمالتها الكبرى", "تُقرأ بالتشديد عنده", "تُحذف ألفها في الوقف", "لا خصوصية لها");
bal("12:26", "«إن الله ليُملي للظالم»", "«الظلم ظلمات يوم القيامة»", "«انصر أخاك ظالمًا أو مظلومًا»", "«اتقوا دعوة المظلوم»");
bal("12:27", "تحريم الركون للظالمين", "وجوب طاعة الظالم في كل أمر", "جواز إعانة الظالم عند الحاجة", "لا حكم في الآية");
bal("12:28", "تكفّل الله بالرزق", "ترك العمل والتوكل وحده", "أن الرزق بالحيلة والذكاء", "أن البشر يرزقون الدواب");
bal("12:29", "أن الحاكم هو الله", "أن العقل هو الحاكم والمشرّع", "أن العرف هو الحاكم", "أن الحكم للأكثرية دائمًا");
bal("12:30", "العفة والاستعاذة", "الهروب من المسؤولية", "مجاراة الفتنة ثم التوبة", "الاعتماد على النفس وحدها");

