bal("11:0", "كثير التضرّع والدعاء", "كثير الأسفار والتنقّل", "كثير الأولاد والذرية", "كثير الكلام والجدال");
bal("11:2", "كعب ومرارة وهلال", "أبو بكر وعمر وعثمان", "ثلاثة من رؤوس المنافقين", "ثلاثة من أعراب البادية");
bal("11:3", "أبو طالب", "عبد الله بن أبي بن سلول", "أبو جهل بن هشام", "آمنة أم النبي ﷺ وحدها");
bal("11:4", "هشاشة عمل المنافقين", "قوة البناء في الإسلام وثباته", "وصف مسجد قباء وبنائه", "زلزال أصاب المدينة");
bal("11:5", "النظر إلى وجه الله", "مضاعفة الحسنات فقط", "زيادة العمر في الدنيا", "زيادة المال والولد");
bal("11:6", "آمنوا فكُشف عنهم العذاب", "أُغرقوا جميعًا في البحر", "مُسخوا قردة وخنازير", "أُهلكوا بالصيحة");
bal("11:8", "سكان البادية", "العرب عامة في كل مكان", "أهل مكة من قريش", "أهل الكتاب في المدينة");
bal("11:10", "مسجد بناه المنافقون للكيد", "مسجد في مكة هدمه المشركون", "مسجد بُني بلا إذن الوالي", "مسجد القبلتين في المدينة");
bal("11:11", "أبو لبابة وأصحابه", "كعب بن مالك وصاحباه", "المنافقون المتخلفون", "الأعراب المعتذرون");
bal("11:12", "أهل قباء", "أهل الصُّفّة", "المهاجرون الأولون", "أهل مكة بعد الفتح");
bal("11:13", "استعارة", "تشبيه بليغ", "كناية عن الفقر", "طباق بين البيع والشراء");
bal("11:14", "سرعة زوال الدنيا", "فضل المطر على الأرض", "كثرة النبات بعد المطر", "طرق الزراعة والسقي");
bal("11:15", "سواد وجوه أهل السيئات", "النوم العميق", "ظلام القبر ووحشته", "الخجل من الناس");
bal("11:17", "فضل الله ورحمته", "جمع الأموال والتجارة", "الانتصار على الناس في الجدال", "الشهرة وحسن السمعة");
bal("11:18", "إخراج جسده عبرةً", "نجاته من الموت غرقًا", "نجاته من العذاب في الآخرة", "دخوله الجنة بعد إيمانه");
bal("11:19", "الإتيان بسورة مثله", "الإتيان بالقرآن كله", "إحياء الموتى من القبور", "تسيير الجبال عن مكة");
bal("11:21", "لأنه آمن عند معاينة الهلاك", "لأنه لم يقلها بالعربية", "لأنه قالها سرًّا في نفسه", "لأن موسى لم يسمعه");
bal("11:25", "خُتمت شدّتها بالرحمة", "لا مناسبة بين الختام والسورة", "لأن الآية في أحكام الزكاة", "لأن الآية قصة من القصص");
bal("11:26", "تختبر / تقرأ", "لا فرق في المعنى", "«تتلو» تعني تنسى", "«تبلو» تعني تبكي");
bal("11:27", "كان يدعو للمتصدّق", "كان يصلي عليهم صلاة الجنازة", "كان يردّ الصدقة على صاحبها", "لم يكن يدعو لأحد منهم");
bal("11:28", "أخذ الإمام الزكاة والدعاء", "أن الزكاة اختيارية لمن شاء", "تحريم الدعاء للمتصدق", "أن الزكاة للإمام خاصة");
bal("11:29", "إذن الله", "قرابة الشافع من المشفوع له", "كثرة مال الشافع وجاهه", "لا شرط للشفاعة");
bal("11:30", "الواجب الكفائي", "الواجب العيني على كل أحد", "المباح المستوي الطرفين", "المكروه كراهة تنزيه");
bal("11:31", "القرآن شفاء للقلوب", "القرآن للتبرك فقط", "القرآن يُقرأ على الأموات", "القرآن كتاب تاريخ وأخبار");

