bal("10:0", "النساء والمتخلفون", "الخلفاء الراشدون من بعده", "الأعداء المحاربون", "المسافرون في التجارة");
bal("10:2", "بعد صلاته على ابن أُبيّ", "بعد وفاة أبي طالب عمّه", "بعد غزوة بدر الكبرى", "عند وفاة النجاشي ملك الحبشة");
bal("10:3", "استعارة تمثيلية", "تشبيه بليغ", "كناية عن الصفة", "طباق بين النور والظلام");
bal("10:4", "أبو بكر", "علي بن أبي طالب", "عمر بن الخطاب", "بلال بن رباح");
bal("10:6", "لأنها نزلت بالبراءة، والبسملة أمان", "لأنها سقطت سهوًا عند كتابة المصحف", "لأنها أول سورة نزلت في المدينة", "لأنها قصيرة لا تحتاج إلى بسملة");
