bal("10:11", "تبوك", "بدر", "أحد", "الخندق");
bal("10:12", "استهزاء المنافقين في تبوك", "مزاح بعض الصحابة فيما بينهم", "لعب الصبيان في المدينة", "سباق الخيل بين الصحابة");
bal("10:13", "أن تأليف القلوب من الله", "فضل الإنفاق على كسب القلوب", "قلّة المال عند المسلمين", "تفرّق الأنصار قبل الإسلام");
bal("10:14", "مقابلة وتبكيت", "طباق بين الحر والبرد", "استعارة مكنية", "جناس تام");
bal("10:15", "ترتيب إعراض البخيل عن السائل", "لأنها أكبر أعضاء الجسد", "لمراعاة السجع والفواصل", "لأنها أقل الأعضاء إحساسًا");
bal("10:16", "بالعبادة والبناء", "البناء والتشييد فقط", "الزخرفة والتزيين", "السكن والمبيت فيها");
bal("10:18", "الرمي", "كثرة الجنود والعتاد", "المال والإنفاق", "الإيمان والتقوى");
bal("10:21", "الثبات والذكر والطاعة والصبر", "كثرة العدد", "قوة السلاح فقط", "مفاجأة العدو ليلًا");
bal("10:25", "الولاية ثم البراءة", "لا مناسبة بين السورتين", "كلتاهما في القصص", "كلتاهما من السور المكية");
bal("10:26", "لا عهود / لا تصديق", "لا فرق بين القراءتين", "بالكسر: لا قوة لهم في القتال", "بالفتح: لا مال لهم ولا تجارة");
bal("10:27", "«ما ظنك باثنين الله ثالثهما»", "«اصبر فإن النصر قريب»", "«اخرج وانظر هل تبعونا»", "«لا تخبر أحدًا بمكاننا»");
bal("10:28", "التخميس", "الغنيمة كلها للإمام وحده", "الغنيمة كلها للجيش المقاتل", "تحريم الغنائم على المسلمين");
bal("10:29", "طاعتهم في التحليل والتحريم", "السجود لهم", "تقديم القرابين لهم", "زيارة قبورهم");
bal("10:30", "نسخ الأثقل بالأخف", "نسخ الأخف بالأثقل", "لا نسخ بين الآيتين", "نسخ التلاوة دون الحكم");
bal("10:31", "التوكل مع العمل", "ترك الأسباب والاكتفاء بالدعاء", "الجزع عند نزول المصيبة", "الاعتماد على الناس");

// ======================= الجزء 9 =======================
bal("9:2", "غنائم بدر", "غنائم خيبر وتوزيعها", "أحداث فتح مكة", "غنائم غزوة حنين");
bal("9:3", "من انسلخ من الآيات واتّبع هواه", "الوفاء بالعهد والأمانة", "الشجاعة في القتال", "الصبر على الجوع والعطش");
bal("9:4", "الله أوصل رمية النبي ﷺ", "نفي أن النبي ﷺ رمى أصلًا", "النهي عن الرمي في القتال", "وصف رمي الجمار في الحج");
bal("9:5", "ميثاق الإقرار بالربوبية", "ميثاق بني إسرائيل في التوراة", "بيعة الرضوان تحت الشجرة", "عهد الحديبية مع قريش");
bal("9:8", "مغشيًّا عليه", "ميتًا لا روح فيه", "ساجدًا لله", "هاربًا من الجبل");
bal("9:10", "استغاثته ﷺ يوم بدر", "دعاؤه ﷺ يوم أحد", "دعاؤه ﷺ في طريق الهجرة", "دعاؤه ﷺ في صلاة الاستسقاء");
bal("9:12", "أبو لبابة", "حاطب بن أبي بلتعة وحده", "عبد الله بن أبي بن سلول", "كعب بن الأشرف اليهودي");
bal("9:13", "استعارة مكنية", "تشبيه بليغ", "كناية عن الصمت", "طباق بين الغضب والرضا");
bal("9:14", "تنبّه القلب", "رؤية العين المجردة", "النوم والغفلة", "الخوف والرهبة");
bal("9:15", "سمعوا ولم ينتفعوا", "تناقض بين العبارتين", "كانوا صُمًّا على الحقيقة", "الأول للماضي والثاني للمستقبل");
bal("9:16", "جمعت العفو والمعروف والإعراض", "لأنها أطول آية في السورة", "لأنها في الأحكام الفقهية", "لأنها آخر آية نزلت");
bal("9:17", "الإنصات للقرآن", "القراءة بصوت مرتفع", "الوقوف عند القراءة", "ترك القراءة في الجماعة");
bal("9:18", "ثلاث، ونجا الناهون", "فرقتان، ونجتا معًا", "فرقة واحدة هلكت كلها", "أربع فرق، نجت اثنتان");
bal("9:19", "التقوى وإصلاح ذات البين", "جمع الغنائم وإحصاؤها", "قتل الأسرى", "الهجرة إلى المدينة");
bal("9:20", "وجل القلوب", "كثرة المال والإنفاق", "الشجاعة في القتال", "الفصاحة والبيان");
bal("9:21", "العبرة بزمن النزول", "الآية مكية بالضرورة", "السورة كلها مكية", "لا يمكن الحكم عليها");
